CREATE DATABASE IF NOT EXISTS rblx08 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE rblx08;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(20) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,blurb TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen DATETIME NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS games(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,creator_id BIGINT UNSIGNED NULL,title VARCHAR(120) NOT NULL,description TEXT NULL,visits BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(creator_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS catalog_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,type ENUM('hat','shirt','pants','tshirt','face','head','other') NOT NULL DEFAULT 'other',description TEXT NULL,price INT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,item_id BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_inventory(user_id,item_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(item_id) REFERENCES catalog_items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS forum_topics(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(120) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS forum_replies(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,topic_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,body TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(topic_id) REFERENCES forum_topics(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
